CREATE TABLE purchase_case_group_events (
  id INTEGER PRIMARY KEY,
  group_id TEXT NOT NULL UNIQUE CHECK(length(group_id) BETWEEN 3 AND 64),
  need_key TEXT NOT NULL CHECK(length(need_key) BETWEEN 1 AND 120),
  selection_hash TEXT NOT NULL UNIQUE CHECK(length(selection_hash)=64),
  documentation_outcome TEXT NOT NULL CHECK(documentation_outcome IN ('unresolved','ordinary_evidence_sufficient','alternative_evidence_assessed')),
  note TEXT NOT NULL DEFAULT '' CHECK(length(note) <= 2000),
  event_hash TEXT NOT NULL UNIQUE CHECK(length(event_hash)=64),
  actor TEXT NOT NULL CHECK(length(trim(actor)) BETWEEN 1 AND 256),
  program TEXT NOT NULL CHECK(length(trim(program)) BETWEEN 1 AND 256),
  created_at TEXT NOT NULL
);
CREATE TABLE purchase_case_group_members (
  id INTEGER PRIMARY KEY,
  group_event_id INTEGER NOT NULL REFERENCES purchase_case_group_events(id),
  case_id TEXT NOT NULL,
  case_version INTEGER NOT NULL CHECK(case_version > 0),
  source_fingerprint TEXT NOT NULL CHECK(length(source_fingerprint)=64),
  case_event_hash TEXT NOT NULL UNIQUE CHECK(length(case_event_hash)=64),
  UNIQUE(group_event_id,case_id)
);
CREATE INDEX purchase_case_group_members_case ON purchase_case_group_members(case_id,case_version DESC);
CREATE TRIGGER purchase_case_group_events_no_update BEFORE UPDATE ON purchase_case_group_events BEGIN SELECT RAISE(ABORT,'purchase case groups are append-only'); END;
CREATE TRIGGER purchase_case_group_events_no_delete BEFORE DELETE ON purchase_case_group_events BEGIN SELECT RAISE(ABORT,'purchase case groups are append-only'); END;
CREATE TRIGGER purchase_case_group_members_no_update BEFORE UPDATE ON purchase_case_group_members BEGIN SELECT RAISE(ABORT,'purchase case group members are append-only'); END;
CREATE TRIGGER purchase_case_group_members_no_delete BEFORE DELETE ON purchase_case_group_members BEGIN SELECT RAISE(ABORT,'purchase case group members are append-only'); END;
